cases = [
    ("Merhaba Dünya!", "merhaba-dunya"),
    ("İstanbul", "istanbul"),
    ("Işık", "isik"),
    ("  a -- b  ", "a-b"),
    ("a -- b", "a-b"),
    ("!!!", "bos"),
]

def passes(implementation):
    return all(implementation(title) == expected for title, expected in cases)

for name in input().split():
    print(f"{name}: {'GEÇTİ' if passes(IMPLS[name]) else 'YAKALANDI'}")
